INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (1, 'Understanding Clear Aligner Treatment: What to Expect', 'assets/image/infycare-logo.png', 'Crowded Teeth & Overbite', 'Moderate', '6 Months', 18, 'Clear aligners have revolutionized modern orthodontics. Unlike traditional metal braces, custom 3D printed aligners are virtually invisible, comfortable to wear, and removable for dining and oral hygiene.', '2026-08-17 19:21:08', '2026-08-17 19:21:08') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (12, 'Rayapati story', 'assets/image/infycare-logo.png', 'spacing', 'Simple', '8 months', 30, '"I had small gaps between my teeth that always bothered me. I chose Mydent Aligners, and I couldn’t be happier! In just 8 months, my smile completely changed. The aligners were clear, comfortable, and fit perfectly into my daily routine. The support from the Mydent team was excellent throughout the journey. I now smile with pride, thanks to Mydent!"\\r\\n\\r\\n⭐️⭐️⭐️⭐️⭐️', '2025-07-08 09:47:44', '2025-08-01 09:15:25') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (13, 'teja story', 'assets/image/infycare-logo.png', 'spacing', 'Moderate', '14', 52, '“I always felt conscious about the gaps in my teeth. I didn’t want metal braces, so I chose Mydent Aligners – and it was the best decision.\\r\\n\\r\\nOver 14 months and 52 aligners, my smile changed completely. The aligners were comfortable, easy to wear, and almost invisible.\\r\\n\\r\\nThe team supported me throughout the journey, and I could see visible changes every month. Now, I feel so much more confident when I smile.\\r\\n\\r\\nThank you, Mydent, for giving me the smile I always wanted!”\\r\\n\\r\\n— Teja R., Mydent Patient', '2025-07-08 10:01:28', '2025-08-01 09:15:14') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (14, 'kaif story', 'assets/image/infycare-logo.png', 'crowding', 'Severe', '14', 42, '“My teeth were crowded and uneven, and it always made me hesitate to smile in photos. I wanted a solution that was discreet and effective – that’s when I found Mydent Aligners.\\r\\n\\r\\nWith just 42 aligners, my teeth started shifting into place beautifully. The aligners were comfortable, easy to remove, and nobody even noticed I was wearing them.\\r\\n\\r\\nThe process was smooth, and the results were amazing. My smile looks aligned and clean now – and I feel more confident every day.\\r\\n\\r\\nMydent made the journey simple and stress-free. Highly recommended!”\\r\\n\\r\\n— Kaif M', '2025-07-08 10:04:27', '2025-08-01 09:15:04') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (15, 'yunus story', 'assets/image/infycare-logo.png', 'underbite', 'Severe', '18 months', 48, '“I had a severe underbite that made it hard for me to chew properly and affected my confidence. I always thought I’d need surgery or braces, but then I discovered Mydent Aligners.\\r\\n\\r\\nFrom the start, the team explained everything clearly and planned a treatment just for me. It wasn’t easy, but the aligners worked better than I imagined.\\r\\n\\r\\nMy bite slowly improved, and now my teeth are aligned properly. No brackets, no wires – just a smooth, step-by-step transformation.\\r\\n\\r\\nI’m really thankful to Mydent for handling a tough case like mine with such care and expertise.”\\r\\n\\r\\n— Yunus A., Mydent Patient', '2025-07-08 10:07:30', '2025-08-01 09:14:48') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (16, 'sowjanya story', 'assets/image/infycare-logo.png', 'open bite', 'Severe', '28 months', 64, '“As a mother, I was very worried about my daughter Sowjanya’s teeth. She had a severe open bite, and it affected her chewing and speech. I thought only surgery could fix it.\\r\\n\\r\\nBut when we consulted Mydent Aligners, the doctors assured us that it could be corrected with their advanced treatment. They explained every step, and we felt confident moving forward.\\r\\n\\r\\nOver time, we started seeing visible changes. Her bite improved, her smile became more natural, and most importantly, her confidence grew.\\r\\n\\r\\nI’m truly thankful to the Mydent team for treating my daughter with such care and expertise. They made what felt impossible, possible – without any surgery or pain.”\\r\\n\\r\\n— Sowjanya’s Mother', '2025-07-08 10:09:50', '2025-08-01 09:14:37') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (17, 'sumanth story', 'assets/image/infycare-logo.png', 'crowding', 'Simple', '6months', 20, '“I had mild crowding in my front teeth that always bothered me when I smiled. It wasn’t a big issue, but I still wanted to fix it.\\r\\n\\r\\nI chose Mydent Aligners because I wanted a clear and comfortable option. The process was super smooth – no pain, no hassle.\\r\\n\\r\\nWithin a few months, I could see a big difference. My teeth look aligned, and my smile feels more confident now.\\r\\n\\r\\nFor anyone with a simple case like mine, I’d definitely recommend Mydent. It’s easy, effective, and worth it.”\\r\\n\\r\\n— Sumanth, ill give 5starts out of 5', '2025-07-08 10:12:30', '2025-08-01 09:32:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (18, 'Prasad story', 'assets/image/infycare-logo.png', 'open bite', 'Moderate', '12', 46, '“I always knew something was off with my bite, even as a kid. I couldn’t close my mouth fully, and my front teeth never touched. Eating certain foods was difficult, and over time, it started affecting how I spoke too.”\\r\\n\\r\\nMy name is Prasad, and I lived with a moderate open bite for years. People would say it’s not noticeable, but for me, it was always there — in every photo, in every meal, and in every moment I hesitated to smile.\\r\\n\\r\\nI had consulted a few dentists in the past, and most of them suggested traditional braces. Some even mentioned surgery down the line. I wasn’t ready for that. I wanted something simpler, less painful, and more suited to my lifestyle.\\r\\n\\r\\nThat’s when I found Mydent Aligners. From the first consultation, I felt hopeful. The team was professional, patient, and took the time to explain everything about open bite correction using aligners. I was amazed that even my moderate case could be handled without braces or surgery.\\r\\n\\r\\nThe treatment was planned in detail. Each aligner was designed to gradually shift my teeth, and with every new set, I could feel the progress. The best part? It was invisible. I continued working, attending events, and living my life without anyone noticing I was undergoing treatment.\\r\\n\\r\\nOver the months, my bite started to close. I could finally bite into foods I used to avoid. My speech improved naturally, and so did my self-esteem.\\r\\n\\r\\nToday, my teeth look aligned, my bite is functional, and I smile without thinking twice.\\r\\n\\r\\nMydent Aligners changed not just my teeth, but how I carry myself in life. I’ll always be grateful for that.”\\r\\n\\r\\n— Prasad M., Mydent Patient', '2025-07-08 10:14:33', '2025-08-01 09:14:26') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (19, 'suhas story', 'assets/image/infycare-logo.png', 'spacing', 'Moderate', '11', 36, '“I had visible gaps between my teeth that always made me feel self-conscious. Even though it wasn’t a severe problem, I used to avoid smiling in pictures or speaking freely in groups.\\r\\n\\r\\nAfter hearing about Mydent Aligners, I decided to give it a try. From the very first scan, the process was smooth and professional. The treatment plan was explained clearly, and I felt confident moving forward.\\r\\n\\r\\nI was given a series of aligners to gradually close the gaps, and within a few months, I could already see the difference. The aligners were easy to wear, comfortable, and barely noticeable.\\r\\n\\r\\nNow, my smile looks balanced and clean – and the confidence it’s given me is priceless. I’m really happy I chose Mydent for my smile journey.”\\r\\n\\r\\n— Suhas', '2025-07-08 10:16:07', '2025-08-01 09:14:14') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (20, 'pavan story', 'assets/image/infycare-logo.png', 'spacing', 'Moderate', '14', 40, '“I had a moderate alignment issue that always made me feel uncomfortable about my smile. It wasn’t extreme, but noticeable enough that it bothered me.\\r\\n\\r\\nI didn’t want traditional braces because of how they look and feel. That’s when I found out about Mydent Aligners, and it turned out to be the perfect solution.\\r\\n\\r\\nThe team did a free scan and gave me a clear plan. The aligners fit well, were easy to manage, and the entire treatment was so smooth.\\r\\n\\r\\nOver the next few months, I started noticing steady changes. My teeth began to align properly, and I didn’t face any pain or speech issues.\\r\\n\\r\\nNow, my smile is more natural and confident. I’m glad I trusted Mydent – they made the whole experience simple and stress-free.”\\r\\n\\r\\n— Pavan, Mydent Patient', '2025-07-08 10:17:36', '2025-08-01 09:14:02') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (21, 'Anandu story', 'assets/image/infycare-logo.png', 'spacing', 'Simple', '8', 24, 'The gaps between my teeth were something I wanted to fix quickly and comfortably, so I chose aligners. The treatment took about 8 months, and the process was straightforward. My dentist was always supportive and clear with explanations. I’m really happy with how my teeth look now.\\r\\n— Anandu', '2025-07-08 10:19:36', '2025-08-01 09:13:50') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (22, 'Bhargavi story', 'assets/image/infycare-logo.png', 'missing', 'Severe', '18', 48, 'I had several missing teeth and was always self-conscious about my smile. After consulting with my dentist, I decided to go ahead with aligner treatment. It took around 18 months, and I couldn’t be happier with the results. The process was smooth, comfortable, and barely noticeable to others. My confidence has improved so much, and I finally feel proud to smile again. Thank you for the incredible care and support throughout my journey!"\\r\\n— Bhargavi', '2025-07-08 10:21:20', '2025-08-01 09:13:11') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (23, 'Manvitha story', 'assets/image/infycare-logo.png', 'crowding', 'Severe', '16', 48, '“I had severe crowding in my teeth for as long as I can remember. My front teeth overlapped badly, and my smile always made me feel insecure.\\r\\n\\r\\nI used to cover my mouth while talking or smiling in public. I was afraid that braces would be painful and too visible, especially as an adult. That’s when I came across Mydent Aligners.\\r\\n\\r\\nThe team was so reassuring during my first consultation. They explained that even severe cases like mine could be treated effectively with aligners – and that gave me hope.\\r\\n\\r\\nThe treatment was detailed and well-monitored. I received a series of aligners and, step by step, my teeth started shifting into proper alignment. It wasn’t always easy, but it was completely worth it.\\r\\n\\r\\nToday, I look at my smile and feel proud. My teeth are straight, my confidence is back, and all of this happened without metal braces or surgery.\\r\\n\\r\\nThank you, Mydent, for transforming my smile and making me believe it was possible.”\\r\\n\\r\\n— Manvitha', '2025-07-08 10:25:40', '2025-08-01 09:12:52') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (24, 'Ganesh story', 'assets/image/infycare-logo.png', 'spacing', 'Severe', '18 months', 48, '"For a long time, I was bothered by the gaps between my teeth. When I chose to get aligners, I wasn’t sure what to expect, but it turned out to be way easier than I imagined. The aligners felt really comfortable, and I barely noticed them while wearing. My dentist was great — always ready to answer my questions and keep me on track. Now, my teeth look awesome and those gaps are completely gone. I’m super happy with the whole experience!"\\r\\n— Ganesh', '2025-07-08 10:26:53', '2025-08-01 09:15:58') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (25, 'Rajitha story', 'assets/image/infycare-logo.png', 'spacing', 'Simple', '4months', 20, '"I underwent aligner therapy to correct the spacing between my teeth. The treatment was efficient and comfortable, and my dentist provided clear guidance and excellent care throughout. I’m very pleased with the results and feel more confident with my smile now."\\r\\n— Rajitha', '2025-07-08 10:28:24', '2025-08-01 09:12:42') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (26, 'Reddy story', 'assets/image/infycare-logo.png', 'spacing', 'Moderate', '8 months', 30, '"I had gaps between my teeth that always made me hesitant to smile. Choosing aligners was a game-changer, and I couldn’t believe how effective and easy the treatment was. My dentist was incredibly supportive from the beginning — always available to answer questions, monitor my progress, and adjust the plan when needed. The care I received felt very personalized, and I always felt like I was in safe hands. Now, my smile looks perfect and natural. I couldn’t be more satisfied with the results and the care I received."\\r\\n— Reddy', '2025-07-08 10:29:53', '2025-08-01 09:12:27') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (27, 'Veerababu story', 'assets/image/infycare-logo.png', 'Forwardly placed', 'Moderate', '12 months', 36, '"My front teeth used to stick out, and it always made me feel awkward, especially when I smiled or talked. I was really conscious of how they looked, and it even affected my confidence. I avoided smiling in pictures and often felt uncomfortable around people.\\r\\n\\r\\nThen I found out about MyDent Aligners. My dentist told me they could help fix the position of my teeth without the need for metal braces. I decided to go for it, and honestly, it was one of the best decisions I’ve made.\\r\\n\\r\\nThe aligners were clear, easy to wear, and no one even noticed I had them on. Over time, I could actually see my teeth moving into the right place. There was no pain, just a bit of pressure at the beginning — but totally manageable.\\r\\n\\r\\nNow my teeth look straight and natural, and my smile has completely changed. I feel so much more confident in myself. I’m really happy with the results, and I’d definitely recommend mydent Aligners* to anyone who wants to fix their teeth without the hassle of traditional braces."', '2025-07-08 10:31:21', '2025-08-01 09:12:11') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `thumbnail`, `issue_type`, `issue_level`, `treatment_time`, `aligner_count`, `content`, `created_at`, `updated_at`) VALUES (28, 'Nikhil story', 'assets/image/infycare-logo.png', 'spacing', 'Simple', '4 months', 10, '"I had small gaps between my front teeth that not only made me feel self-conscious but also caused food to get stuck every time I ate. It was frustrating and sometimes even embarrassing. I felt like I had to brush my teeth constantly just to keep them clean. It also made me hesitate to smile in photos or when meeting new people.\\r\\n\\r\\nWhen I finally talked to my dentist about it, they explained the reasons behind the spacing and introduced me to MyDent Aligners as a simple and effective solution to close the gaps. I was a bit nervous at first, but they explained everything clearly, and the whole process was much easier than I expected. The aligners were comfortable, barely noticeable, and didn’t interfere with my daily routine.\\r\\n\\r\\nNow that the treatment is complete, my smile looks more even, and my bite feels more natural. Eating is no longer a hassle, and I don’t worry about food getting stuck anymore. The best part is that I can smile freely and confidently without feeling awkward. Looking back, I honestly wish I had started mydent Aligners sooner. The results were better than I expected, and I’m so glad I chose this treatment."', '2025-07-08 10:32:37', '2025-08-01 09:11:51') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `articles` (`id`, `title`, `content`, `thumbnail`, `created_at`, `updated_at`) VALUES (1, 'Top 5 Oral Hygiene Practices for Aligner Wearers', 'Maintaining optimal oral hygiene while undergoing clear aligner treatment is key to achieving a healthy, bright smile. Always brush after meals and clean your aligner trays daily with mild soap and water.', 'assets/image/infycare-logo.png', '2026-08-17 19:21:16', '2026-08-17 19:21:16') ON DUPLICATE KEY UPDATE `id`=`id`;
